// A phase gate expressed in code: nothing moves forward until the
// previous phase produced its artifact.
public enum Phase {
    REQUIREMENTS, ANALYSIS, DESIGN, DEVELOPMENT, TESTING, DEPLOYMENT, MAINTENANCE
}

public class Project {
    private Phase phase = Phase.REQUIREMENTS;
    private final Map<Phase, String> artifacts = new EnumMap<>(Phase.class);

    public void complete(Phase p, String artifact) {
        if (p != phase) throw new IllegalStateException("Project is still in " + phase);
        artifacts.put(p, artifact);
        Phase[] all = Phase.values();
        phase = all[Math.min(p.ordinal() + 1, all.length - 1)];
    }

    public Phase current() { return phase; }
}

