interface Repository { Optional<Order> find(long id); }

class JdbcRepository implements Repository {
    public Optional<Order> find(long id) { /* SQL */ return Optional.empty(); }
}

class LoggingRepository implements Repository {
    private final Repository inner;
    LoggingRepository(Repository inner) { this.inner = inner; }
    public Optional<Order> find(long id) {
        long t = System.nanoTime();
        try { return inner.find(id); }
        finally { System.out.println("find(" + id + ") took " + (System.nanoTime() - t) + "ns"); }
    }
}

class CachingRepository implements Repository {
    private final Repository inner;
    private final Map<Long, Order> cache = new ConcurrentHashMap<>();
    CachingRepository(Repository inner) { this.inner = inner; }
    public Optional<Order> find(long id) {
        Order hit = cache.get(id);
        if (hit != null) return Optional.of(hit);
        Optional<Order> found = inner.find(id);
        found.ifPresent(o -> cache.put(id, o));
        return found;
    }
}

Repository repo = new CachingRepository(new LoggingRepository(new JdbcRepository()));

