class DocumentProxy implements Document {
    private final String path;
    private final User user;
    private RealDocument delegate;                              // created lazily

    DocumentProxy(String path, User user) { this.path = path; this.user = user; }

    public String content() {
        if (!user.canRead(path)) throw new AccessDeniedException(path);
        if (delegate == null) delegate = new RealDocument(path);
        return delegate.content();
    }
}

