public class Feed implements Iterable<Post> {

    private final PostApi api;

    @Override
    public Iterator<Post> iterator() {
        return new Iterator<>() {
            private List<Post> page = api.page(0);
            private int index = 0, pageNo = 0;

            public boolean hasNext() {
                if (index < page.size()) return true;
                page = api.page(++pageNo); index = 0;
                return !page.isEmpty();
            }

            public Post next() { return page.get(index++); }
        };
    }
}

