public interface FormMediator { void changed(Component source); }

public class BookingForm implements FormMediator {

    private final DatePicker date = new DatePicker(this);
    private final RoomList rooms = new RoomList(this);
    private final PriceLabel price = new PriceLabel(this);

    @Override
    public void changed(Component source) {
        if (source == date) { rooms.reload(date.value()); price.recalculate(); }
        else if (source == rooms) { price.recalculate(); }
    }
}

