public class Editor {

    private String text;

    public record Snapshot(String text) { }               // opaque to everyone else

    public Snapshot save() { return new Snapshot(text); }
    public void restore(Snapshot s) { this.text = s.text(); }
}

public class History {
    private final Deque<Editor.Snapshot> stack = new ArrayDeque<>();
    public void push(Editor.Snapshot s) { stack.push(s); }
    public Editor.Snapshot pop() { return stack.pop(); }
}

