@Service
public class DraftService {

    private final RedisTemplate<String, DocumentSnapshot> redis;

    public void checkpoint(Document doc) {
        redis.opsForList().leftPush("draft:" + doc.id(), doc.snapshot());
    }

    public void undo(Document doc) {
        doc.restore(redis.opsForList().leftPop("draft:" + doc.id()));
    }
}

