public interface Visitor<R> {
    R visit(Item item);
    R visit(Discount discount);
}

public interface Node { <R> R accept(Visitor<R> visitor); }

public record Item(String name, long paise) implements Node {
    public <R> R accept(Visitor<R> v) { return v.visit(this); }
}

public class TotalVisitor implements Visitor<Long> {
    public Long visit(Item i) { return i.paise(); }
    public Long visit(Discount d) { return -d.paise(); }
}

concepts.springCode:
sealed interface Node permits Item, Discount { }

@Service
class TotalCalculator {
    long total(List<Node> nodes) {
        return nodes.stream().mapToLong(n -> switch (n) {   // pattern matching
            case Item i -> i.paise();
            case Discount d -> -d.paise();
        }).sum();
    }
}

