public abstract class Approver {

    private Approver next;

    public Approver linkTo(Approver next) { this.next = next; return next; }

    public void handle(Expense expense) {
        if (canApprove(expense)) { approve(expense); return; }
        if (next != null) next.handle(expense);
        else throw new IllegalStateException("nobody can approve " + expense);
    }

    protected abstract boolean canApprove(Expense expense);
    protected abstract void approve(Expense expense);
}

