public interface Expression { boolean interpret(Customer c); }

public record OlderThan(int age) implements Expression {
    public boolean interpret(Customer c) { return c.age() > age; }
}

public record IsVip() implements Expression {
    public boolean interpret(Customer c) { return c.vip(); }
}

public record And(Expression left, Expression right) implements Expression {
    public boolean interpret(Customer c) {
        return left.interpret(c) && right.interpret(c);
    }
}

